-- Synthetic data only. This suite is run in a temporary local PostgreSQL.
BEGIN;
DO $$
DECLARE company uuid:='11111111-1111-1111-1111-111111111111'; driver uuid:='c1000000-0000-0000-0000-000000000001';
 route uuid; addr uuid; task uuid; next_task uuid; token text:=repeat('a',64); payload jsonb; result jsonb;
 car uuid; angle text; reservation jsonb; rev int; blocked boolean; previous_expiry timestamptz;
BEGIN
 PERFORM set_config('request.jwt.claim.sub','cccccccc-cccc-cccc-cccc-cccccccccccc',true);
 SELECT id INTO car FROM public.veiculos_motoristas WHERE user_id=auth.uid();
 FOREACH angle IN ARRAY ARRAY['frente','lado_direito','lado_esquerdo','traseira'] LOOP
  reservation:=public.reservar_upload_evidencia(company,'foto_veiculo',angle||'.jpg',angle);
  INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('veiculos-documentos',reservation->>'storage_path','{"size":500,"mimetype":"image/jpeg"}');
  PERFORM public.anexar_documento_veiculo(car,'foto_veiculo',angle||'.jpg',reservation->>'storage_path',500,angle);
 END LOOP;
 reservation:=public.reservar_upload_evidencia(company,'crlv','crlv.pdf');
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('veiculos-documentos',reservation->>'storage_path','{"size":500,"mimetype":"application/pdf"}');
 PERFORM public.anexar_documento_veiculo(car,'crlv','crlv.pdf',reservation->>'storage_path',500);
 PERFORM set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',true);
 SELECT revisao INTO rev FROM public.veiculos_motoristas WHERE id=car;
 PERFORM public.analisar_veiculo_motorista(car,true,rev);
 PERFORM public.configurar_nome_empresa(company,'Empresa de acompanhamento');
 payload:=jsonb_build_object('empresa_id',company,'nome_identificador','Local teste','destinatario_padrao','302','endereco_completo','Rua teste, 30, Palhoça','latitude',-27.63,'longitude',-48.68,'numero','30','bairro','Centro','cidade','Palhoça','cep','88100000');
 result:=public.salvar_cliente_endereco(payload); addr:=(result->>'id')::uuid;
 result:=public.salvar_cliente_endereco(payload||'{"whatsapp_cliente":"5548999990000"}'::jsonb);
 IF result->'cliente'->>'destinatario_padrao'<>'302' OR result->'cliente'->>'whatsapp_cliente'<>'5548999990000' THEN RAISE EXCEPTION 'Apartment/telephone mixed'; END IF;
 result:=public.salvar_cliente_endereco(payload);
 IF result->'cliente'->>'whatsapp_cliente'<>'5548999990000' THEN RAISE EXCEPTION 'Old client overwrote telephone'; END IF;
 result:=public.salvar_cliente_endereco(payload||'{"whatsapp_cliente":null}'::jsonb);
 IF result->'cliente'->>'whatsapp_cliente' IS NOT NULL OR result->'cliente'->>'destinatario_padrao'<>'302' THEN RAISE EXCEPTION 'Clear phone damaged apartment'; END IF;
 payload:=jsonb_build_object('empresa_id',company,'motorista_id',driver,'idempotency_key','tracking-flow','distancia_original_km',10,'tempo_original_minutos',20,'distancia_otimizada_km',10,'tempo_otimizado_minutos',20,'percentual_economia_km',0,'percentual_economia_tempo',0,'ordem_paradas_json','[]'::jsonb,
 'paradas',jsonb_build_array(jsonb_build_object('cliente_endereco_id',addr,'destinatario_nome','INTERNAL SECRET','destinatario_telefone','5548999990000','unidade_apartamento','302','tipo_tarefa','entrega'),jsonb_build_object('cliente_endereco_id',addr,'destinatario_nome','OTHER SECRET','tipo_tarefa','coleta')));
 result:=public.enviar_pedidos_motorista(payload); route:=(result->>'nova_rota_id')::uuid;
 IF route IS NULL THEN RAISE EXCEPTION 'Dispatch failed: %',result; END IF;
 SELECT id INTO task FROM public.entregas WHERE rota_id=route AND tipo_tarefa='entrega';
 SELECT id INTO next_task FROM public.entregas WHERE rota_id=route AND tipo_tarefa='coleta';
 IF (SELECT destinatario_telefone FROM public.entregas WHERE id=task)<>'5548999990000' THEN RAISE EXCEPTION 'Dispatch lost phone'; END IF;
 PERFORM set_config('request.jwt.claim.sub','cccccccc-cccc-cccc-cccc-cccccccccccc',true);
 PERFORM public.aceitar_pedidos_motorista(ARRAY[task,next_task]);
 UPDATE public.rotas_planejadas SET status='em_execucao' WHERE id=route;
 blocked:=false; BEGIN PERFORM public.preparar_aviso_cliente(task,token); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Shared uncollected delivery'; END IF;
 PERFORM public.confirmar_retirada_pedidos(ARRAY[task]);
 blocked:=false; BEGIN PERFORM public.preparar_aviso_cliente(next_task,token); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Shared another stop'; END IF;
 result:=public.preparar_aviso_cliente(task,token);
 IF result->>'sucesso'<>'true' OR result->>'empresa_nome'<>'Empresa de acompanhamento' OR result->>'motorista_nome'<>(SELECT COALESCE(NULLIF(btrim(p.nome),''),m.nome) FROM public.motoristas m LEFT JOIN public.perfis_usuarios p ON p.id=m.user_id WHERE m.id=driver) THEN RAISE EXCEPTION 'Wrong company/profile: %',result; END IF;
 SELECT expires_at INTO previous_expiry FROM ec_private.customer_tracking WHERE entrega_id=task;
 PERFORM public.preparar_aviso_cliente(task,token);
 IF (SELECT count(*) FROM ec_private.customer_tracking)<>1 OR (SELECT expires_at FROM ec_private.customer_tracking WHERE entrega_id=task)<>previous_expiry THEN RAISE EXCEPTION 'Retry rotated or extended token'; END IF;
 result:=public.publicar_localizacao_acompanhamento(task,-27.62,-48.67,now()-interval '3 minutes',NULL);
 IF result->>'sucesso'<>'false' THEN RAISE EXCEPTION 'Old GPS accepted'; END IF;
 result:=public.publicar_localizacao_acompanhamento(task,-27.62,-48.67,now(),now()+interval '10 minutes');
 IF result->>'sucesso'<>'true' THEN RAISE EXCEPTION 'Fresh GPS rejected'; END IF;
 result:=public.publicar_localizacao_acompanhamento(task,-27.61,-48.66,now()-interval '1 minute',NULL);
 IF result->>'sucesso'<>'false' THEN RAISE EXCEPTION 'Out-of-order GPS accepted'; END IF;
 PERFORM set_config('request.jwt.claim.sub','ffffffff-ffff-ffff-ffff-ffffffffffff',true);
 blocked:=false; BEGIN PERFORM public.preparar_aviso_cliente(task,repeat('b',64)); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Other driver issued link'; END IF;
 blocked:=false; BEGIN PERFORM public.configurar_nome_empresa(company,'Foreign'); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Other company renamed'; END IF;
 result:=public.publicar_localizacao_acompanhamento(task,0,0,now()+interval '1 second',NULL);
 IF result->>'sucesso'<>'false' THEN RAISE EXCEPTION 'Other driver published'; END IF;
 PERFORM set_config('request.jwt.claim.sub','',true);
 result:=public.obter_acompanhamento_cliente(token);
 IF result->>'estado'<>'ativo' OR result->'posicao'->>'latitude'<>'-27.62' THEN RAISE EXCEPTION 'Public view failed: %',result; END IF;
 IF result ?| ARRAY['destinatario_nome','telefone','motorista_id','rota_id','paradas','entrega_id','observacoes_gestor'] OR result::text LIKE '%SECRET%' THEN RAISE EXCEPTION 'Public data leak'; END IF;
 IF public.obter_acompanhamento_cliente(repeat('b',64))->>'estado'<>'indisponivel' OR public.obter_acompanhamento_cliente(task::text)->>'estado'<>'indisponivel' THEN RAISE EXCEPTION 'Guessable link'; END IF;
 UPDATE public.entregas SET destinatario_telefone='5548999990001' WHERE id=task;
 IF public.obter_acompanhamento_cliente(token)->>'estado'<>'encerrado' THEN RAISE EXCEPTION 'Former recipient can see changed recipient'; END IF;
 UPDATE public.entregas SET destinatario_telefone='5548999990000' WHERE id=task;
 UPDATE ec_private.customer_tracking SET observed_at=now()-interval '10 minutes' WHERE entrega_id=task;
 IF (public.obter_acompanhamento_cliente(token)->>'atualizada_em')::timestamptz<>now()-interval '10 minutes' THEN RAISE EXCEPTION 'Stale time masked'; END IF;
 UPDATE public.empresa_membros SET status='suspenso' WHERE motorista_id=driver;
 IF public.obter_acompanhamento_cliente(token)->>'estado'<>'encerrado' THEN RAISE EXCEPTION 'Suspended driver visible'; END IF;
 UPDATE public.empresa_membros SET status='aprovado' WHERE motorista_id=driver;
 UPDATE public.rotas_planejadas SET status='concluida' WHERE id=route;
 IF public.obter_acompanhamento_cliente(token) ? 'posicao' THEN RAISE EXCEPTION 'Closed route visible'; END IF;
 UPDATE public.rotas_planejadas SET status='em_execucao' WHERE id=route;
 UPDATE public.entregas SET status='entregue' WHERE id=task;
 IF public.obter_acompanhamento_cliente(token)->>'estado'<>'encerrado' OR public.obter_acompanhamento_cliente(token) ? 'destino' THEN RAISE EXCEPTION 'Completed delivery visible'; END IF;
 UPDATE public.entregas SET status='tentativa_falha' WHERE id=task;
 IF public.obter_acompanhamento_cliente(token) ? 'posicao' THEN RAISE EXCEPTION 'Failed delivery visible'; END IF;
 UPDATE public.entregas SET status='cancelada' WHERE id=task;
 IF public.obter_acompanhamento_cliente(token) ? 'posicao' THEN RAISE EXCEPTION 'Cancelled delivery visible'; END IF;
 IF has_schema_privilege('anon','ec_private','USAGE') OR has_table_privilege('authenticated','ec_private.customer_tracking','SELECT') OR has_function_privilege('anon','public.preparar_aviso_cliente(uuid,text)','EXECUTE') OR NOT has_function_privilege('anon','public.obter_acompanhamento_cliente(text)','EXECUTE') THEN RAISE EXCEPTION 'Wrong endpoint permissions'; END IF;
END $$;
SET LOCAL ROLE anon;
DO $$ BEGIN IF public.obter_acompanhamento_cliente(repeat('a',64))->>'estado'<>'encerrado' THEN RAISE EXCEPTION 'Anonymous role cannot read terminal state'; END IF; END $$;
RESET ROLE;
ROLLBACK;
SELECT 'passed' AS tracking_result;
